def calculate_average(numbers):
    if not numbers:
        return 0
    return sum(numbers) / len(numbers)

def calculate_median(numbers):
    if not numbers:
        return 0
    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    if n % 2 == 1:
        return sorted_numbers[n // 2]
    else:
        return (sorted_numbers[n // 2 - 1] + sorted_numbers[n // 2]) / 2

def calculate_mode(numbers):
    if not numbers:
        return []
    frequency = {}
    for num in numbers:
        frequency[num] = frequency.get(num, 0) + 1
    max_frequency = max(frequency.values())
    modes = [num for num, freq in frequency.items() if freq == max_frequency]
    return modes

def calculate_range(numbers):
    if not numbers:
        return 0
    return max(numbers) - min(numbers)

def calculate_standard_deviation(numbers):
    if not numbers:
        return 0
    mean = calculate_average(numbers)
    variance = sum((x - mean) ** 2 for x in numbers) / len(numbers)
    return variance ** 0.5

def calculate_variance(numbers):
    if not numbers:
        return 0
    mean = calculate_average(numbers)
    return sum((x - mean) ** 2 for x in numbers) / len(numbers)

def calculate_quartiles(numbers):
    if not numbers:
        return [0, 0, 0]
    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)
    q1 = sorted_numbers[n // 4]
    q2 = sorted_numbers[n // 2]
    q3 = sorted_numbers[3 * n // 4]
    return [q1, q2, q3]

def calculate_percentile(numbers, percentile):
    if not numbers:
        return 0
    sorted_numbers = sorted(numbers)
    index = (percentile / 100) * (len(sorted_numbers) - 1)
    lower_index = int(index)
    upper_index = lower_index + 1
    if upper_index >= len(sorted_numbers):
        return sorted_numbers[lower_index]
    lower_value = sorted_numbers[lower_index]
    upper_value = sorted_numbers[upper_index]
    fraction = index - lower_index
    return lower_value + fraction * (upper_value - lower_value)

def calculate_coefficient_of_variation(numbers):
    if not numbers:
        return 0
    mean = calculate_average(numbers)
    std_dev = calculate_standard_deviation(numbers)
    if mean == 0:
        return 0
    return (std_dev / mean) * 100

def calculate_skewness(numbers):
    if not numbers:
        return 0
    mean = calculate_average(numbers)
    std_dev = calculate_standard_deviation(numbers)
    if std_dev == 0:
        return 0
    n = len(numbers)
    skewness = sum((x - mean) ** 3 for x in numbers) / (n * std_dev ** 3)
    return skewness

def calculate_kurtosis(numbers):
    if not numbers:
        return 0
    mean = calculate_average(numbers)
    std_dev = calculate_standard_deviation(numbers)
    if std_dev == 0:
        return 0
    n = len(numbers)
    kurtosis = sum((x - mean) ** 4 for x in numbers) / (n * std_dev ** 4) - 3
    return kurtosis

def calculate_correlation(x, y):
    if not x or not y or len(x) != len(y):
        return 0
    n = len(x)
    mean_x = calculate_average(x)
    mean_y = calculate_average(y)
    numerator = sum((x[i] - mean_x) * (y[i] - mean_y) for i in range(n))
    denominator = (sum((x[i] - mean_x) ** 2 for i in range(n)) * sum((y[i] - mean_y) ** 2 for i in range(n))) ** 0.5
    if denominator == 0:
        return 0
    return numerator / denominator

def calculate_covariance(x, y):
    if not x or not y or len(x) != len(y):
        return 0
    mean_x = calculate_average(x)
    mean_y = calculate_average(y)
    n = len(x)
    covariance = sum((x[i] - mean_x) * (y[i] - mean_y) for i in range(n)) / n
    return covariance

def calculate_moving_average(numbers, window_size):
    if not numbers or window_size <= 0:
        return []
    moving_averages = []
    for i in range(len(numbers) - window_size + 1):
        window = numbers[i:i + window_size]
        moving_averages.append(sum(window) / window_size)
    return moving_averages

def calculate_exponential_moving_average(numbers, alpha):
    if not numbers or alpha <= 0 or alpha >= 1:
        return []
    ema = [numbers[0]]
    for i in range(1, len(numbers)):
        ema.append(alpha * numbers[i] + (1 - alpha) * ema[-1])
    return ema

def calculate_cumulative_sum(numbers):
    if not numbers:
        return []
    cumulative_sums = []
    total = 0
    for num in numbers:
        total += num
        cumulative_sums.append(total)
    return cumulative_sums

def calculate_cumulative_product(numbers):
    if not numbers:
        return []
    cumulative_products = []
    total = 1
    for num in numbers:
        total *= num
        cumulative_products.append(total)
    return cumulative_products

def calculate_cumulative_max(numbers):
    if not numbers:
        return []
    cumulative_maxes = []
    current_max = numbers[0]
    for num in numbers:
        current_max = max(current_max, num)
        cumulative_maxes.append(current_max)
    return cumulative_maxes

def calculate_cumulative_min(numbers):
    if not numbers:
